import { useState, useEffect } from 'react'

const API_BASE = 'http://127.0.0.1:8001/api'

function AeoTracker() {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    // In the future this will be a real LLM connection. 
    // For now we will fetch mock tracking data from Go.
    fetch(`${API_BASE}/advertising/aeo`)
      .then(res => res.json())
      .then(d => {
        setData(d)
        setLoading(false)
      })
      .catch(err => {
        console.error(err)
        // Set some dummy data if backend is not ready
        setData({
          overall_score: 72,
          prompts: [
            { query: "Fast-paced sci-fi thriller", ranking: 3, visibility: "High" },
            { query: "Cyberpunk book 2026", ranking: 8, visibility: "Medium" }
          ],
          suggestions: [
            "Optimize Amazon reviews to include 'cyberpunk'.",
            "Write a Medium listicle targeting 'Sci-fi thriller books'."
          ]
        })
        setLoading(false)
      })
  }, [])

  if (loading) {
    return <div className="glass-panel"><h2>Loading AEO Tracker...</h2></div>
  }

  return (
    <div className="aeo-container">
      <div className="glass-panel">
        <h2>AI Engine Optimization (AEO)</h2>
        <p className="aeo-subtitle">Track how often LLMs recommend your product.</p>
        
        <div className="aeo-score-card">
          <div className="score-circle">
            <span className="score-value">{data?.overall_score || 0}</span>
            <span className="score-label">/ 100</span>
          </div>
          <div className="score-info">
            <h3>Overall AI Share of Voice</h3>
            <p>Your product is moderately visible across major AI platforms (ChatGPT, Gemini). Optimizing reviews and cross-platform mentions will increase this score.</p>
          </div>
        </div>
      </div>

      <div className="grid">
        <div className="glass-panel">
          <h3>Targeted Prompts Tracker</h3>
          <ul className="prompt-list">
            {data?.prompts?.map((p, idx) => (
              <li key={idx} className="prompt-item">
                <div className="prompt-query">"{p.query}"</div>
                <div className="prompt-stats">
                  <span className={`badge ${p.visibility.toLowerCase()}`}>
                    {p.visibility}
                  </span>
                  <span>Rank: #{p.ranking}</span>
                </div>
              </li>
            ))}
          </ul>
          <button className="btn-primary mt-3">+ Add New Prompt</button>
        </div>

        <div className="glass-panel">
          <h3>Optimization Suggestions</h3>
          <ul className="suggestion-list">
            {data?.suggestions?.map((s, idx) => (
              <li key={idx} className="suggestion-item">
                <span className="bullet">💡</span> {s}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  )
}

export default AeoTracker
